/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void exec_init (const UInt8 task_num)
{	
	UInt8 n ;

	exec_q_pending = q_create () ;

	for (n = 0 ; n < task_num ; n++)
	{
		Tsk tsk_exec = (Tsk) os_mem_request (sizeof (Tsk)) ;		

		if( tsk_exec && exec_q_pending )
		{
			tsk_exec = os_tsk_create (exec_task, TASK_EXEC_PRI, TASK_EXEC_STK, 0, TASK_EXEC_NAME) ;

			os_tsk_start (tsk_exec , 0) ;
		}
	}
}

